class TextExtractor(html.parser.HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []
        self.skip = 0
        self.skiptags = {'script','style','nav','header','footer'}
    def handle_starttag(self, tag, attrs):
        if tag in self.skiptags:
            self.skip += 1
        if tag in ('p','div','h1','h2','h3','h4','li','tr','br','section','article'):
            self.parts.append('\n')
        if tag in ('h1','h2','h3','h4'):
            self.parts.append('\n## ')
        if tag in ('td','th'):
            self.parts.append(' | ')
    def handle_endtag(self, tag):
        if tag in self.skiptags and self.skip > 0:
            self.skip -= 1
    def handle_data(self, data):
        if not self.skip:
            self.parts.append(data)

