		t.Errorf("stdout should not contain log lines: %s", stdout.String())
	}
}

func TestCreateDoesNotCreateOutputDirWhenValidationFails(t *testing.T) {
	srv := newBlueprintServer(t, "v1")
	defer srv.Close()

	outDir := filepath.Join(t.TempDir(), "out")
	err := Create(context.Background(), CreateOptions{
		Blueprint:     "test-blueprint",
		OutputDir:     outDir,
		Version:       "v1",
		NoInput:       true,
		Stderr:        &bytes.Buffer{},
		HTTP:          srv.Client(),
		Owner:         "o",
		Repo:          "r",
		GitHubBaseURL: srv.URL,
	})
	if err == nil || !strings.Contains(err.Error(), "missing required parameter") {
		t.Fatalf("expected missing required parameter error, got %v", err)
	}
	if _, statErr := os.Stat(outDir); !os.IsNotExist(statErr) {
		t.Fatalf("failed create should not create output dir, stat err=%v", statErr)
	}
}

func TestCreateReadsStdinValues(t *testing.T) {
	srv := newBlueprintServer(t, "v1")
	defer srv.Close()

	outDir := filepath.Join(t.TempDir(), "out")
	jsonPath := filepath.Join(t.TempDir(), "result.json")

	err := Create(context.Background(), CreateOptions{
		Blueprint:     "test-blueprint",
		OutputDir:     outDir,
		Version:       "v1",
		Files:         []string{StdinValuesPath},
		NoInput:       true,
		OutputJSON:    jsonPath,
		Stdin:         bytes.NewBufferString(`{"integrationName": "from-stdin", "namespace": "ns2"}`),
		Stderr:        &bytes.Buffer{},
		HTTP:          srv.Client(),
		Owner:         "o",
		Repo:          "r",
		GitHubBaseURL: srv.URL,
	})
	if err != nil {
		t.Fatalf("Create: %v", err)
	}

	readme, err := os.ReadFile(filepath.Join(outDir, "README.md"))
	if err != nil {
		t.Fatal(err)
	}
	if string(readme) != "from-stdin in ns2\n" {
		t.Errorf("README = %q", string(readme))
	}

	data, _ := os.ReadFile(jsonPath)
	if !bytes.Contains(data, []byte(`"namespace": "ns2"`)) {
		t.Errorf("result JSON missing namespace value: %s", string(data))
	}
}

package blueprint

import (
	"bytes"
	"context"
	"encoding/json"
	"strings"
	"testing"
)

func TestDescribe(t *testing.T) {
	srv := newBlueprintServer(t, "v1.2.3")
	defer srv.Close()

	got, err := Describe(context.Background(), DescribeOptions{
		Blueprint:     "test-blueprint",
		Version:       "v1.2.3",
		HTTP:          srv.Client(),
		Owner:         "o",
		Repo:          "r",
		GitHubBaseURL: srv.URL,
	})
	if err != nil {
		t.Fatalf("Describe: %v", err)
	}
	if got.Template != "test-blueprint" {
		t.Errorf("Template = %q", got.Template)
	}
	if got.Version != "v1.2.3" {
		t.Errorf("Version = %q", got.Version)
	}
	if got.Parameters == nil {
		t.Fatal("Parameters is nil")
	}
	if got.Parameters["type"] != "object" {
		t.Errorf("parameters.type = %v", got.Parameters["type"])
	}
	props, _ := got.Parameters["properties"].(map[string]any)
	if _, ok := props["integrationName"]; !ok {
		t.Errorf("parameters.properties.integrationName missing")
	}
}

func TestDescribeJSONStable(t *testing.T) {
	srv := newBlueprintServer(t, "v1")
	defer srv.Close()

	got, err := Describe(context.Background(), DescribeOptions{
		Blueprint:     "test-blueprint",
		Version:       "v1",
		HTTP:          srv.Client(),
		Owner:         "o",
		Repo:          "r",
		GitHubBaseURL: srv.URL,
	})
	if err != nil {
		t.Fatalf("Describe: %v", err)
	}
	data, err := json.Marshal(got)
	if err != nil {
		t.Fatal(err)
	}
	// Pin the public field names. Adding new fields is fine; renaming/removing
	// these breaks downstream Backstage consumers.
	for _, key := range []string{
		`"blueprint":`, `"owner":`, `"repo":`, `"version":`,
		`"parameters":`,
	} {
		if !strings.Contains(string(data), key) {
			t.Errorf("missing key %s in JSON: %s", key, string(data))
		}
	}
}

func TestDescribeFormatTextPreservesDeclarationOrder(t *testing.T) {
	srv := newBlueprintServer(t, "v1")
	defer srv.Close()

	got, err := Describe(context.Background(), DescribeOptions{
		Blueprint:     "test-blueprint",
		Version:       "v1",
		HTTP:          srv.Client(),
		Owner:         "o",
		Repo:          "r",
		GitHubBaseURL: srv.URL,
	})
	if err != nil {
		t.Fatal(err)
	}
	var buf bytes.Buffer
	got.FormatText(&buf)
	out := buf.String()
	iName := strings.Index(out, "integrationName")
	iNamespace := strings.Index(out, "namespace")
	if iName < 0 || iNamespace < 0 {
		t.Fatalf("expected both fields in output: %s", out)
	}
	if iName > iNamespace {
		t.Errorf("expected integrationName before namespace (YAML declaration order), got:\n%s", out)
	}
}

