1	package blueprint
2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"io"
8		"net/http"
9		"os"
10		"path/filepath"
11	)
12	
13	const (
14		defaultBlueprintOwner = "integrio-intropy"
15		defaultBlueprintRepo  = "intropy-templates"
16		templateManifestName  = "template.yaml"
17		blueprintSkeletonDir  = "skeleton"
18		githubAPIBaseURL      = "https://api.github.com"
19	)
20	
21	// GitHub talks to a GitHub-compatible API. BaseURL is overridable for tests.
22	type GitHub struct {
23		BaseURL   string
24		HTTP      *http.Client
25		Token     string
26		UserAgent string
27	}
28	
29	func newGitHub(client *http.Client, userAgent string) *GitHub {
30		if client == nil {
31			client = http.DefaultClient
32		}
33		return &GitHub{
34			BaseURL:   githubAPIBaseURL,
35			HTTP:      client,
36			Token:     os.Getenv("GITHUB_TOKEN"),
37			UserAgent: userAgent,
38		}
39	}
40	
41	// NewGitHubClient creates a configured GitHub client for external callers.
42	func NewGitHubClient(client *http.Client, userAgent, baseURL string) *GitHub {
43		gh := newGitHub(client, userAgent)
44		if baseURL != "" {
45			gh.BaseURL = baseURL
46		}
47		return gh
48	}
49	
50	func newConfiguredGitHub(client *http.Client, userAgent, baseURL string) *GitHub {
51		return NewGitHubClient(client, userAgent, baseURL)
52	}
53	
54	func resolveReleaseTag(ctx context.Context, gh *GitHub, owner, repo, requestedTag string) (string, error) {
55		return gh.ResolveTag(ctx, owner, repo, requestedTag)
56	}
57	
58	// ResolveTag returns requestedTag as-is when set, otherwise the latest
59	// release tag for owner/repo.
60	func (g *GitHub) ResolveTag(ctx context.Context, owner, repo, requestedTag string) (string, error) {
61		if requestedTag != "" {
62			return requestedTag, nil
63		}
64		return g.LatestTag(ctx, owner, repo)
65	}
66	
67	// DownloadBlueprint fetches the repo tarball at tag, extracts it to a temp
68	// dir (created with tempPattern), and returns the path of the named blueprint
69	// subdirectory plus a cleanup func that removes the temp dir.
70	func DownloadBlueprint(ctx context.Context, gh *GitHub, owner, repo, tag, blueprint, tempPattern string) (string, func(), error) {
71		return downloadBlueprint(ctx, gh, owner, repo, tag, blueprint, tempPattern)
72	}
73	
74	func downloadBlueprint(ctx context.Context, gh *GitHub, owner, repo, tag, blueprint, tempPattern string) (string, func(), error) {
75		rc, err := gh.Tarball(ctx, owner, repo, tag)
76		if err != nil {
77			return "", nil, err
78		}
79		defer rc.Close()
80	
81		tmpDir, err := os.MkdirTemp("", tempPattern)
82		if err != nil {
83			return "", nil, err
84		}
85		cleanup := func() { _ = os.RemoveAll(tmpDir) }
86	
87		if err := ExtractTarGz(rc, tmpDir); err != nil {
88			cleanup()
89			return "", nil, err
90		}
91	
92		blueprintRoot := filepath.Join(tmpDir, blueprint)
93		if info, err := os.Stat(blueprintRoot); err != nil || !info.IsDir() {
94			cleanup()
95			return "", nil, fmt.Errorf("template %q not found in %s/%s@%s", blueprint, owner, repo, tag)
96		}
97		return blueprintRoot, cleanup, nil
98	}
99	
100	// LatestTag returns the tag_name of the most recent release for owner/repo.
101	func (g *GitHub) LatestTag(ctx context.Context, owner, repo string) (string, error) {
102		u := fmt.Sprintf("%s/repos/%s/%s/releases/latest", g.BaseURL, owner, repo)
103		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
104		if err != nil {
105			return "", err
106		}
107		req.Header.Set("Accept", "application/vnd.github+json")
108		g.addCommonHeaders(req)
109	
110		resp, err := g.HTTP.Do(req)
111		if err != nil {
112			return "", fmt.Errorf("github releases: %w", err)
113		}
114		defer resp.Body.Close()
115		if resp.StatusCode != http.StatusOK {
116			body, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
117			return "", fmt.Errorf("github releases: %s: %s", resp.Status, string(body))
118		}
119		var rel struct {
120			TagName string `json:"tag_name"`
121		}
122		if err := json.NewDecoder(resp.Body).Decode(&rel); err != nil {
123			return "", fmt.Errorf("decode release: %w", err)
124		}
125		if rel.TagName == "" {
126			return "", fmt.Errorf("github releases: empty tag_name")
127		}
128		return rel.TagName, nil
129	}
130	
131	// Tarball returns a streaming reader of the gzipped tar for owner/repo at tag.
132	// The caller must Close the returned ReadCloser.
133	func (g *GitHub) Tarball(ctx context.Context, owner, repo, tag string) (io.ReadCloser, error) {
134		u := fmt.Sprintf("%s/repos/%s/%s/tarball/%s", g.BaseURL, owner, repo, tag)
135		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u, nil)
136		if err != nil {
137			return nil, err
138		}
139		g.addCommonHeaders(req)
140	
141		resp, err := g.HTTP.Do(req)
142		if err != nil {
143			return nil, fmt.Errorf("download tarball: %w", err)
144		}
145		if resp.StatusCode != http.StatusOK {
146			body, _ := io.ReadAll(io.LimitReader(resp.Body, 4096))
147			resp.Body.Close()
148			return nil, fmt.Errorf("download tarball: %s: %s", resp.Status, string(body))
149		}
150		return resp.Body, nil
151	}
152	
153	// ListBlueprints returns the names of blueprint directories at the root of
154	// the blueprints repository. On any error an empty slice is returned.
155	func (g *GitHub) ListBlueprints(ctx context.Context, owner, repo string) ([]string, error) {
156		if owner == "" {
157			owner = defaultBlueprintOwner
158		}
159		if repo == "" {
160			repo = defaultBlueprintRepo
161		}
